window.ECBA_QUESTION_BANK=window.ECBA_QUESTION_BANK||[];window.ECBA_QUESTION_BANK.push(...[{"id":"q588","domains":[5],"level":3,"tag":"","q":"Which option best matches the stakeholder roles listed for Prioritize Requirements in BABOK Guide v3?","opts":["Customer, Domain Subject Matter Expert, End User, Implementation Subject Matter Expert, Project Manager, Regulator, Sponsor","Customer, Domain Subject Matter Expert, End User, Supplier, Sponsor","Domain Subject Matter Expert, Project Manager, Sponsor, Regulator only","Customer, End User, Operational Support, Tester, Supplier"],"answer":[0],"why":["Correct: this set reflects the §5.3 stakeholder list, including the Domain Subject Matter Expert correction in BABOK errata.","This omits several listed roles and substitutes Supplier.","This omits Customer, End User, Implementation SME, and other listed roles.","This is a plausible group but does not match the §5.3 stakeholder list."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–90; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q589","domains":[5],"level":1,"tag":"","q":"What is the purpose of Specify and Model Requirements?","opts":["Analyze, synthesize, and refine elicitation results into requirements and designs","Ensure requirements and designs align with business requirements and support needed value","Rank requirements and designs in relative importance","Check elicitation results for accuracy and consistency"],"answer":[0],"why":["Correct: this is the purpose of §7.1.","This is the purpose of Validate Requirements.","This is the purpose of Prioritize Requirements.","This is the purpose of Confirm Elicitation Results."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q590","domains":[5],"level":2,"tag":"","q":"Which input-to-output pair corresponds to Specify and Model Requirements?","opts":["Elicitation Results (any state) → Requirements (Specified and Modelled)","Elicitation Results (Unconfirmed) → Elicitation Results (Confirmed)","Requirements (Specified and Modelled) → Requirements (Validated)","Requirements and Designs → Requirements (Prioritized)"],"answer":[0],"why":["Correct: §7.1 accepts Elicitation Results in any state and produces Requirements (Specified and Modelled).","This is the input/output pair for Confirm Elicitation Results.","This is the input/output pair for Validate Requirements.","This is the input/output pair for Prioritize Requirements, although that task also produces Designs (Prioritized)."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q591","domains":[5],"level":3,"tag":"","q":"Which resources are listed as guidelines and tools for Specify and Model Requirements?","opts":["Modelling Notations/Standards, Modelling Tools, Requirements Architecture, Requirements Life Cycle Management Tools, Solution Scope","Business Objectives, Future State Description, Potential Value, Solution Scope","Business Constraints, Change Strategy, Domain Knowledge, Governance Approach","Elicitation Activity Plan and Existing Business Analysis Information"],"answer":[0],"why":["Correct: these are the guidelines and tools listed for §7.1; BABOK errata clarifies the life cycle management tool name.","These guide Validate Requirements.","These guide Prioritize Requirements.","These guide Confirm Elicitation Results."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q592","domains":[5],"level":4,"tag":"","q":"Which are techniques frequently used in Specify and Model Requirements?","opts":["Acceptance and Evaluation Criteria","Data Modelling","Interface Analysis","Prioritization"],"answer":[0,1,2],"why":["Correct: Acceptance and Evaluation Criteria is listed for §7.1.","Correct: Data Modelling is listed for §7.1.","Correct: Interface Analysis is listed for §7.1.","Prioritization is a technique used for Prioritize Requirements, not in the frequently used §7.1 list."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-13.html"},{"id":"q593","domains":[5],"level":5,"tag":"","q":"Which statement matches the stakeholder guidance for Specify and Model Requirements?","opts":["Any stakeholder may participate when they have relevant knowledge or experience","Only the Sponsor and Project Manager may participate","Only implementation roles may participate","Only the Domain Subject Matter Expert may participate"],"answer":[0],"why":["Correct: §7.1 allows any stakeholder to participate; the BA may also perform the task and package results for review.","The task is not limited to these two roles.","The task is not limited to implementation roles.","The task is not restricted to one stakeholder role."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q594","domains":[5],"level":4,"tag":"","q":"Which statement describes a model as used when specifying and modelling requirements?","opts":["A descriptive and visual way to convey information to a specific audience to support analysis, communication, and understanding","A ranked list that records the relative importance of requirements","A confirmation that elicitation information is accurate and consistent","An approval record that authorizes implementation"],"answer":[0],"why":["Correct: this is the BABOK concept of a model in §7.1.","A ranked list is prioritization information.","Accuracy and consistency checking belongs to Confirm Elicitation Results.","Approval is handled through governance and approval tasks."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q595","domains":[5],"level":1,"tag":"","q":"Which statements are part of the purpose and elements of Validate Requirements?","opts":["Ensure requirements and designs align with business requirements and support needed value","Identify assumptions so associated risks can be managed","Define measurable evaluation criteria","Rank requirements in order of relative importance"],"answer":[0,1,2],"why":["Correct: this captures the task purpose.","Correct: identifying assumptions is an element of §7.3.","Correct: defining measurable evaluation criteria is an element of §7.3.","Ranking relative importance is the purpose of Prioritize Requirements."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–147; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-13.html"},{"id":"q596","domains":[5],"level":2,"tag":"","q":"Which input is listed for Validate Requirements?","opts":["Requirements (Specified and Modelled)","Requirements (Verified) only","Elicitation Results (Unconfirmed)","Requirements (Prioritized) and Designs (Prioritized) only"],"answer":[0],"why":["Correct: §7.3 takes Requirements (Specified and Modelled) as input.","Verification is a prerequisite for completing validation, but the specified task input is Requirements (Specified and Modelled).","This is an input to Confirm Elicitation Results.","Prioritized requirements are not the specified input to §7.3."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–147; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q597","domains":[5],"level":3,"tag":"","q":"What output is produced by Validate Requirements?","opts":["Requirements (Validated)","Requirements (Verified)","Elicitation Results (Confirmed)","Requirements (Approved)"],"answer":[0],"why":["Correct: §7.3 produces Requirements (Validated).","Verified requirements are produced by Verify Requirements.","Confirmed elicitation results are produced by Confirm Elicitation Results.","Approved requirements are produced by Approve Requirements."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–147; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q598","domains":[5],"level":4,"tag":"","q":"Which are guidelines and tools listed for Validate Requirements?","opts":["Business Objectives","Future State Description","Potential Value","Governance Approach"],"answer":[0,1,2],"why":["Correct: Business Objectives are listed for §7.3.","Correct: Future State Description is listed for §7.3.","Correct: Potential Value is listed for §7.3.","Governance Approach is listed for Prioritize Requirements, not Validate Requirements."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–147; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-13.html"},{"id":"q599","domains":[5],"level":5,"tag":"","q":"Which are techniques listed for Validate Requirements?","opts":["Acceptance and Evaluation Criteria","Financial Analysis","Metrics and Key Performance Indicators (KPIs)","Prioritization"],"answer":[0,1,2],"why":["Correct: Acceptance and Evaluation Criteria is listed for §7.3.","Correct: Financial Analysis is listed for §7.3.","Correct: Metrics and KPIs are listed for §7.3.","Prioritization is a technique used for Prioritize Requirements, not the listed §7.3 technique."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–147; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-13.html"},{"id":"q600","domains":[5],"level":5,"tag":"","q":"Which statement best matches the stakeholders for Validate Requirements?","opts":["All stakeholders; the BA works with the customer, end users, and sponsors, and virtually all project stakeholders may be involved","Only the Sponsor and Project Manager","Only the Customer and End User","Only subject matter experts who authored the requirements"],"answer":[0],"why":["Correct: §7.3.7 identifies All stakeholders and notes the BA works with the customer, end users, and sponsors.","This excludes stakeholders with relevant knowledge and experience.","This omits the BA, sponsors, and other project stakeholders.","Validation is not limited to authors; other stakeholders may identify problematic requirements."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–147; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q601","domains":[5],"level":1,"tag":"","q":"What is the purpose of Plan Business Analysis Information Management?","opts":["Define how business analysis information will be stored, accessed, and maintained","Establish how requirements will be traced to solution components","Determine how stakeholders will be engaged during elicitation","Set the approval authority for requirements changes"],"answer":[0],"why":["Correct: the Information Management Approach defines the organization and management of business analysis information.","Tracing is addressed in Trace Requirements.","Stakeholder engagement is covered by the Stakeholder Engagement Approach.","Change approval authority belongs to governance."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–46; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q602","domains":[5],"level":2,"tag":"","q":"Which are inputs to Plan Business Analysis Information Management?","opts":["Governance Approach","Stakeholder Engagement Approach","Requirements (Specified and Modelled)","Business Analysis Approach"],"answer":[0,1,3],"why":["Correct: Governance Approach is an input.","Correct: Stakeholder Engagement Approach is an input.","Requirements (Specified and Modelled) is not a listed input to this task.","Correct: Business Analysis Approach is an input."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–46; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-14.html"},{"id":"q603","domains":[5],"level":3,"tag":"","q":"Which set contains guidelines and tools for Plan Business Analysis Information Management?","opts":["Information Management Approach, Requirements Management Tools/Repository, Solution Scope","Business Objectives, Current State Description, Potential Value","Business Analysis Performance Assessment, Business Policies, Information Management Tools, Legal/Regulatory Information","Business Analysis Approach, Governance Approach, Stakeholder Engagement Approach"],"answer":[2],"why":["These are associated with other tasks and are not the listed guidelines/tools for §3.4.","These are not the listed §3.4 guidelines and tools.","Correct: these are the listed guidelines and tools for §3.4.","These are the task inputs."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–46; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q604","domains":[5],"level":4,"tag":"","q":"What is the purpose of Maintain Requirements?","opts":["Confirm that requirements satisfy stakeholder needs and business objectives","Ensure requirements and designs remain accurate and current throughout their life cycle","Ensure requirements are linked across related levels and components","Assess the impact of a proposed change on requirements and designs"],"answer":[1],"why":["This describes Validate Requirements.","Correct: maintenance keeps requirements and designs accurate and current as changes occur.","This describes Trace Requirements.","This describes Assess Requirements Changes."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–85; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q605","domains":[5],"level":5,"tag":"","q":"Which statements about inputs and outputs of Maintain Requirements are correct?","opts":["Requirements and Designs are inputs","Requirements (Maintained) is an output","Designs (Maintained) is an output","Requirements (Traced) is the only output"],"answer":[0,1,2],"why":["Correct: Requirements is an input.","Correct: maintained requirements are an output.","Correct: maintained designs are an output.","Requirements (Traced) is an output of Trace Requirements, not the only output here."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–85; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-14.html"},{"id":"q606","domains":[5],"level":1,"tag":"","q":"Which set contains techniques specifically listed for Maintain Requirements?","opts":["Business Rules Analysis, Decision Analysis, Vendor Assessment","Data Modelling, Functional Decomposition, Scope Modelling","Use Cases and Scenarios, Risk Analysis and Management, Interviews","Business Rules Analysis, Data Modelling, Use Cases and Scenarios"],"answer":[3],"why":["Decision Analysis and Vendor Assessment are associated with other tasks.","Functional Decomposition and Scope Modelling are associated with defining requirements architecture.","Risk Analysis and Management and Interviews are not in this selected task technique list.","Correct: Business Rules Analysis, Data Modelling, and Use Cases and Scenarios are listed techniques for maintaining requirements."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–85; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q607","domains":[5],"level":2,"tag":"","q":"What is the purpose of Trace Requirements?","opts":["Assess the value of a proposed change before approval","Verify that requirements are expressed consistently and unambiguously","Ensure requirements and designs at different levels are aligned and manage the effects of change","Keep requirements and designs accurate and current as they evolve"],"answer":[2],"why":["This is Assess Requirements Changes.","This is Verify Requirements.","Correct: traceability establishes and maintains relationships among requirements and designs and supports impact analysis.","This is Maintain Requirements."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 79–82; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q608","domains":[5],"level":3,"tag":"","q":"Which outcomes are produced by Trace Requirements?","opts":["Requirements Change Assessment","Requirements (Traced)","Designs (Traced)","Requirements (Maintained)"],"answer":[1,2],"why":["Requirements Change Assessment is produced by Assess Requirements Changes.","Correct: Requirements (Traced) is an output.","Correct: Designs (Traced) is an output.","Requirements (Maintained) is produced by Maintain Requirements."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 79–82; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-14.html"},{"id":"q609","domains":[5],"level":4,"tag":"","q":"Which techniques are listed for Trace Requirements?","opts":["Item Tracking and Functional Decomposition","Item Tracking and Decision Analysis","Functional Decomposition and Vendor Assessment","Process Modelling and Risk Analysis and Management"],"answer":[0],"why":["Correct: Item Tracking and Functional Decomposition are listed techniques for tracing.","Decision Analysis is listed for assessing requirements changes.","Vendor Assessment is listed for defining design options.","Risk Analysis and Management is used in other tasks; this pairing is not the trace technique list."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 79–82; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q610","domains":[5],"level":5,"tag":"","q":"What does Assess Requirements Changes determine?","opts":["Whether a proposed change is feasible to implement within solution scope","Whether requirements and designs remain accurate after implementation","Whether the current state should be replaced by the future state","The impacts of a proposed change on value, urgency, and stakeholders"],"answer":[3],"why":["Feasibility is one consideration but does not define the full task purpose.","That describes maintaining requirements and designs.","That relates to defining the future state.","Correct: the task assesses the implications of a change, including its benefit, impact, and urgency, to support a decision."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 91–94; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q611","domains":[5],"level":1,"tag":"","q":"Which are inputs to Assess Requirements Changes?","opts":["Designs","Requirements (Validated) only","Requirements","Proposed Change"],"answer":[0,2,3],"why":["Correct: Designs is an input.","Validated requirements alone are not the complete input set.","Correct: Requirements is an input.","Correct: Proposed Change is an input."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 91–94; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-14.html"},{"id":"q612","domains":[5],"level":2,"tag":"","q":"Which roles are correctly matched to their contribution when assessing a requirements change?","opts":["Regulator: assesses end-user activities; Sponsor: confirms solution operation","Customer: feedback on value impact; End User: information about impact on their activities","Customer: evaluates implementation constraints; End User: authorizes funding","Operational Support: determines value impact; Project Manager: reports impacts on daily use"],"answer":[1],"why":["These role descriptions do not match §5.4.7.","Correct: the Customer provides feedback on impact on value; the End User can describe impacts on their activities.","These descriptions do not match the BABOK role guidance for §5.4.","These contributions are assigned to other roles or do not match the task text."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 91–94; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q613","domains":[5],"level":3,"tag":"","q":"Which statement best describes Define Future State?","opts":["Establish goals and objectives that define what the enterprise wants to be capable of, and identify potential value","Describe the current capabilities and identify their performance gaps","Assess undesirable consequences that may affect a change or future state","Select the design that best implements a defined solution scope"],"answer":[0],"why":["Correct: the task defines desired future capabilities, objectives, and potential value.","This describes current state analysis.","This describes Assess Risks.","This describes evaluating design options."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q614","domains":[5],"level":4,"tag":"","q":"Which are outputs of Define Future State?","opts":["Business Objectives","Potential Value","Risk Analysis Results","Future State Description"],"answer":[0,1,3],"why":["Correct: Business Objectives is an output.","Correct: Potential Value is an output.","Risk Analysis Results is produced by Assess Risks.","Correct: Future State Description is an output."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-14.html"},{"id":"q615","domains":[5],"level":5,"tag":"","q":"Which three stakeholder roles are identified for Define Future State?","opts":["Implementation Subject Matter Expert, Operational Support, Tester","Project Manager, Customer, Regulator","Customer, Domain Subject Matter Expert, End User","Sponsor, Regulator, Supplier"],"answer":[2],"why":["These are not the roles named in §6.2.7.","Project Manager and Regulator are not the listed roles for this task.","Correct: BABOK §6.2.7 identifies Customer, Domain Subject Matter Expert, and End User.","These roles are listed in other task contexts, not as the trio in §6.2.7."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q616","domains":[5],"level":1,"tag":"","q":"What is the purpose of Assess Risks?","opts":["Choose the option with the highest potential value without regard to uncertainty","Understand undesirable consequences of internal and external forces on a change or future state and recommend actions","Identify uncertainty that may affect requirements prioritization only","Determine whether a solution meets defined acceptance criteria"],"answer":[1],"why":["Risk assessment explicitly considers uncertainty and its consequences.","Correct: risk assessment considers undesirable consequences and supports recommendations for addressing them.","The task considers risk to the change/future state broadly, not only prioritization.","This describes evaluation against acceptance criteria."],"ref":"BABOK Guide v3 §6.3 Assess Risks, printed pp. 120–123; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q617","domains":[5],"level":2,"tag":"","q":"Which are techniques listed for Assess Risks?","opts":["Brainstorming","Decision Analysis","Financial Analysis","Root Cause Analysis"],"answer":[0,1,3],"why":["Correct: Brainstorming is listed.","Correct: Decision Analysis is listed.","Financial Analysis is not in the listed techniques for this task.","Correct: Root Cause Analysis is listed."],"ref":"BABOK Guide v3 §6.3 Assess Risks, printed pp. 120–123; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-14.html"},{"id":"q618","domains":[5],"level":3,"tag":"","q":"Which input/output pairing is correct for Assess Risks?","opts":["Proposed Change is the sole input; Requirements Change Assessment is the output","Future State Description is the output; Potential Value is the only input","Risk Analysis Results is an input; Identified Risks is the only output","Business Objectives is an input; Risk Analysis Results is the output"],"answer":[3],"why":["This pairing belongs to Assess Requirements Changes.","Future State Description and Potential Value are outputs of Define Future State.","Risk Analysis Results is the output; Identified Risks is a guideline/tool.","Correct: Business Objectives is an input, and Risk Analysis Results is the output."],"ref":"BABOK Guide v3 §6.3 Assess Risks, printed pp. 120–123; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q619","domains":[5],"level":4,"tag":"","q":"Which element is identified for Specify and Model Requirements?","opts":["Assess Requirements Changes","Define Requirements Architecture","Model Requirements","Validate Requirements"],"answer":[2],"why":["Assess Requirements Changes is a separate task.","Define Requirements Architecture is a separate task.","Correct: Model Requirements is the element described in §7.1.4.","Validate Requirements is a separate task."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q620","domains":[5],"level":5,"tag":"","q":"Which input and output are correctly matched for Specify and Model Requirements?","opts":["Input: Requirements (Traced); output: Requirements (Maintained)","Input: Elicitation Results; output: Requirements (Specified and Modelled)","Input: Requirements (Specified and Modelled); output: Requirements (Validated)","Input: Requirements Architecture; output: Design Options"],"answer":[1],"why":["Maintained requirements are not this task output.","Correct: Elicitation Results are the input, and Requirements (Specified and Modelled) is an output.","The input/output sequence belongs to validation, and its output is not specified and modelled.","These are associated with Define Design Options."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q621","domains":[5],"level":1,"tag":"","q":"Which techniques are specifically listed for Specify and Model Requirements?","opts":["Acceptance and Evaluation Criteria, Data Modelling, Interface Analysis","Data Modelling, Functional Decomposition, Scope Modelling","Interface Analysis, Vendor Assessment, Decision Analysis","Use Cases and Scenarios, Item Tracking, Risk Analysis and Management"],"answer":[0],"why":["Correct: each named technique is listed for §7.1.","Functional Decomposition and Scope Modelling are listed for Define Requirements Architecture.","Vendor Assessment is used for Define Design Options; Decision Analysis is not the listed combination.","Item Tracking and Risk Analysis and Management are not in the selected §7.1 technique list."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q622","domains":[5],"level":2,"tag":"","q":"What is the purpose of Define Requirements Architecture?","opts":["Define the information management approach for storing business analysis information","Specify detailed requirements models for stakeholder review","Assess the effects of proposed requirement changes","Ensure requirements collectively support one another and fit the overall business and solution context"],"answer":[3],"why":["This is Plan Business Analysis Information Management.","This is Specify and Model Requirements.","This is Assess Requirements Changes.","Correct: requirements architecture organizes requirements and their relationships into a coherent structure."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–151; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q623","domains":[5],"level":3,"tag":"","q":"Which are inputs to Define Requirements Architecture?","opts":["Information Management Approach","Design Options","Requirements","Solution Scope"],"answer":[0,2,3],"why":["Correct: Information Management Approach is an input.","Design Options is not a listed input to this task.","Correct: Requirements is an input.","Correct: Solution Scope is an input."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–151; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-14.html"},{"id":"q624","domains":[5],"level":4,"tag":"","q":"Which technique set is listed for Define Requirements Architecture?","opts":["Process Modelling, Root Cause Analysis, Financial Analysis","Data Modelling, Functional Decomposition, Scope Modelling","Data Modelling, Interface Analysis, Vendor Assessment","Functional Decomposition, Decision Analysis, Prioritization"],"answer":[1],"why":["Root Cause Analysis and Financial Analysis are not in the listed technique set.","Correct: these techniques are listed for defining requirements architecture.","Interface Analysis and Vendor Assessment are associated with other tasks.","Decision Analysis and Prioritization are not in this task’s selected technique list."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–151; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q625","domains":[5],"level":5,"tag":"","q":"What is the purpose of Define Design Options?","opts":["Define solution approaches, identify opportunities to improve value, and recommend options for further assessment","Select and approve the final solution design","Assess the effect of a proposed requirement change","Define the requirements architecture and its relationships"],"answer":[0],"why":["Correct: the task develops design options, considers value opportunities, and identifies options for further analysis.","Final selection and approval are beyond defining options.","This is Assess Requirements Changes.","This is Define Requirements Architecture."],"ref":"BABOK Guide v3 §7.5 Define Design Options, printed pp. 152–156; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q626","domains":[5],"level":1,"tag":"","q":"Which inputs are listed for Define Design Options?","opts":["Change Strategy","Requirements (Validated, Prioritized)","Requirements (Traced)","Requirements Architecture"],"answer":[0,1,3],"why":["Correct: Change Strategy is an input.","Correct: prioritized and validated requirements are inputs.","Requirements (Traced) is a guideline/tool rather than the listed input in this pairing.","Correct: Requirements Architecture is an input."],"ref":"BABOK Guide v3 §7.5 Define Design Options, printed pp. 152–156; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-14.html"},{"id":"q627","domains":[5],"level":2,"tag":"","q":"Which stakeholders are specifically identified for Define Design Options?","opts":["Customer, End User, Tester","Sponsor, Project Manager, Supplier","Domain Subject Matter Expert, Implementation Subject Matter Expert, Operational Support","Domain Subject Matter Expert, Regulator, Sponsor"],"answer":[2],"why":["These roles may contribute but are not the specific set named for this task.","This set does not match the roles listed in §7.5.7.","Correct: these roles are specifically identified for the task, along with additional stakeholders.","This role set is associated with other tasks."],"ref":"BABOK Guide v3 §7.5 Define Design Options, printed pp. 152–156; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q628","domains":[5],"level":3,"tag":"","q":"When is Recommend Actions to Increase Solution Value performed?","opts":["During elicitation planning, to choose information storage tools","When a solution or enterprise limitation prevents value from being realized, to recommend actions that increase value","Before defining a future state, to identify all possible business objectives","After solution approval, to maintain requirements and designs"],"answer":[1],"why":["Information storage planning is Plan Business Analysis Information Management.","Correct: the task recommends actions to increase value when limitations prevent a solution from achieving it.","Defining objectives is part of Define Future State.","Maintaining requirements is a separate task and does not define this task’s timing/purpose."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-14.html"},{"id":"q629","domains":[5],"level":4,"tag":"","q":"Which statements correctly identify the input/output relationship for Recommend Actions to Increase Solution Value?","opts":["Solution Limitation is an input","Enterprise Limitation is an input","Recommended Actions is an output","Business Objectives is an input"],"answer":[0,1,2],"why":["Correct: Solution Limitation is an input.","Correct: Enterprise Limitation is an input.","Correct: Recommended Actions is the output.","Business Objectives is a guideline/tool, not an input to this task."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-14.html"},{"id":"q630","domains":[5],"level":5,"tag":"","q":"Which are elements of Recommend Actions to Increase Solution Value?","opts":["Recommendations","Assess Solution Limitations","Define Requirements Architecture","Adjust Solution Performance Measures"],"answer":[0,1,3],"why":["Correct: developing recommendations is an element.","Correct: assessing solution limitations is an element.","Defining requirements architecture is a separate task in §7.4.","Correct: adjusting solution performance measures is an element."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-14.html"},{"id":"q631","domains":[5],"level":1,"tag":"","q":"Which output records the defined approach for how business analysis information will be stored, accessed, and used during and after a change?","opts":["Information Management Approach","Business Analysis Approach","Stakeholder Engagement Approach","Requirements Architecture"],"answer":[0],"why":["Correct: the Information Management Approach defines how business analysis information is stored, accessed, and used.","The Business Analysis Approach describes how business analysis work will be conducted.","The Stakeholder Engagement Approach describes stakeholder collaboration.","Requirements Architecture organizes requirements and their relationships."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–46; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q632","domains":[5],"level":2,"tag":"","q":"Which statements reflect the element Organization of Business Analysis Information?","opts":["Structure helps prevent information from being difficult to locate","Organization helps prevent conflicts and needless duplication","The information is organized only after the solution is implemented","Information is structured for efficient access and use"],"answer":[0,1,3],"why":["Correct: well-structured information is easier to locate.","Correct: structure helps avoid conflicts and unnecessary duplication.","The task plans information management during the change, not solely after implementation.","Correct: organization should support efficient access and use."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–46; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-15.html"},{"id":"q633","domains":[5],"level":3,"tag":"","q":"Which technique is described as helping stakeholders uncover their business analysis information-management needs?","opts":["Vendor Assessment","Acceptance and Evaluation Criteria","Brainstorming","Decision Analysis"],"answer":[2],"why":["Vendor Assessment is used to assess suppliers or products.","Acceptance and Evaluation Criteria define how a solution or requirement will be evaluated.","Correct: Brainstorming can uncover stakeholders’ information-management needs.","Decision Analysis supports evaluating choices, not eliciting these needs as described."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–46; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q634","domains":[5],"level":4,"tag":"","q":"Which statement captures the purpose of Maintain Requirements?","opts":["Confirm requirements are aligned with business goals and deliver potential value","Retain requirement accuracy and consistency through and beyond the change, and support reuse in other solutions","Establish clear relationships between requirements and solution components","Evaluate the impact of a proposed change before deciding whether to implement it"],"answer":[1],"why":["This describes Validate Requirements.","Correct: §5.2 retains accuracy and consistency throughout the requirements life cycle and supports reuse.","This describes Trace Requirements.","This describes Assess Requirements Changes."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–85; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q635","domains":[5],"level":5,"tag":"","q":"Which practices are part of maintaining requirements after an approved change?","opts":["Keep requirements clearly named and defined","Keep them available to stakeholders","Maintain relationships and related information to preserve context and original intent","Replace the original requirement with a new one and discard its context"],"answer":[0,1,2],"why":["Correct: clear names and definitions support ongoing accuracy.","Correct: stakeholders need access to maintained requirements.","Correct: preserving relationships and context helps retain original intent.","Discarding context conflicts with the maintenance guidance."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–85; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-15.html"},{"id":"q636","domains":[5],"level":1,"tag":"","q":"Which guideline/tool directs how requirements will be managed for reuse?","opts":["Governance Approach","Business Analysis Approach","Requirements Architecture","Information Management Approach"],"answer":[3],"why":["Governance Approach defines decision-making and approval processes.","Business Analysis Approach plans the overall business analysis work.","Requirements Architecture organizes requirements and their interrelationships.","Correct: the Information Management Approach indicates how requirements will be managed for reuse."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–85; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q637","domains":[5],"level":2,"tag":"","q":"What does the element Level of Formality require the business analyst to consider when planning traceability?","opts":["The order in which requirements will be implemented","The likelihood and impact of risks to the future state","The value of each link and the nature and use of the relationships being created","The approval authority for each individual requirement"],"answer":[2],"why":["Implementation order relates to prioritization and planning.","Likelihood and impact are assessed in Assess Risks.","Correct: traceability effort and formality consider the value of links and the nature and use of relationships.","Approval authority is governed through governance and approval processes."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 79–82; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q638","domains":[5],"level":3,"tag":"","q":"Which items are guidelines and tools for Trace Requirements?","opts":["Requirements Management Tools/Repository","Domain Knowledge","Information Management Approach","Legal/Regulatory Information"],"answer":[0,1,2,3],"why":["Correct: Requirements Management Tools/Repository store and manage information for tracing.","Correct: Domain Knowledge is listed.","Correct: Information Management Approach informs the traceability approach.","Correct: Legal/Regulatory Information may impose traceability rules."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 79–82; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-15.html"},{"id":"q639","domains":[5],"level":4,"tag":"","q":"Which stakeholder role is associated with recommending requirement relationships for a solution component or release?","opts":["Domain Subject Matter Expert","End User","Customer","Sponsor"],"answer":[0],"why":["Correct: the Domain Subject Matter Expert may recommend which requirements should link to a solution component or release.","End Users may need specific dependency relationships among requirements.","Customers may be consulted about how and when requirements are implemented.","Sponsors may review and authorize change, but this is not the contribution described."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 79–82; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q640","domains":[5],"level":5,"tag":"","q":"Which factors guide the formality of assessing a proposed requirements change?","opts":["Only the number of requirements affected","Only the delivery method selected for the solution","The future-state value, without considering governance or available information","Information available, apparent importance of the change, and governance process"],"answer":[3],"why":["The number affected may inform impact, but it is not the complete guidance.","The delivery approach may influence formality, but is not the only basis.","The BABOK guidance explicitly includes governance and information available.","Correct: these three considerations guide assessment formality."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 91–94; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q641","domains":[5],"level":1,"tag":"","q":"Which outputs result from Assess Requirements Changes?","opts":["Requirements (Maintained)","Requirements (Traced)","Requirements Change Assessment","Designs Change Assessment"],"answer":[2,3],"why":["Maintained requirements are produced by Maintain Requirements.","Traced requirements are produced by Trace Requirements.","Correct: Requirements Change Assessment is an output.","Correct: Designs Change Assessment is an output."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 91–94; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-15.html"},{"id":"q642","domains":[5],"level":2,"tag":"","q":"Which statement accurately describes impact analysis in Assess Requirements Changes?","opts":["It compares solution performance measures after implementation","It evaluates the effect of a proposed change; traceability can help identify those effects","It updates requirements after approval but does not analyze effects","It determines stakeholder engagement techniques before elicitation"],"answer":[1],"why":["This aligns with performance assessment, not requirements-change impact analysis.","Correct: impact analysis evaluates the effects of change, and traceability is useful for it.","Updating after approval is maintenance; this omits the impact assessment.","This describes planning stakeholder engagement or elicitation."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 91–94; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q643","domains":[5],"level":3,"tag":"","q":"Which description distinguishes a business goal from a business objective in defining a future state?","opts":["Goals are generally longer-term, ongoing, and qualitative; objectives make the desired results more specific and measurable","Goals are short-term and measurable; objectives are ongoing and qualitative","Goals describe solution components; objectives describe stakeholder roles","Goals are risks to the future state; objectives are risk responses"],"answer":[0],"why":["Correct: BABOK describes goals as longer-term, ongoing, and qualitative, with objectives expressed more specifically.","This reverses the described distinction.","Goals and objectives describe desired ends, not component and role lists.","Risks and responses are handled in Assess Risks."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q644","domains":[5],"level":4,"tag":"","q":"Which artifacts are outputs of Define Future State?","opts":["Future State Description","Potential Value","Risk Analysis Results","Business Objectives"],"answer":[0,1,3],"why":["Correct: Future State Description is an output.","Correct: Potential Value is an output.","Risk Analysis Results is the output of Assess Risks.","Correct: Business Objectives is an output."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-15.html"},{"id":"q645","domains":[5],"level":5,"tag":"","q":"Which technique helps define and compare measurable criteria for evaluating whether a future state has been achieved?","opts":["Vendor Assessment","Lessons Learned","Acceptance and Evaluation Criteria","Item Tracking"],"answer":[2],"why":["Vendor Assessment evaluates vendors and their offerings.","Lessons Learned captures knowledge from prior work.","Correct: Acceptance and Evaluation Criteria supports defining measurable criteria for evaluation.","Item Tracking manages items such as issues and actions."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q646","domains":[5],"level":1,"tag":"","q":"In the element Unknowns, what uncertainty is considered when assessing a risk?","opts":["Uncertainty about which requirements can be reused","Uncertainty about whether the event or condition will occur and the impact if it does","Uncertainty about which stakeholder owns requirement approval","Uncertainty about the exact model notation to use"],"answer":[1],"why":["Reuse is addressed by Maintain Requirements.","Correct: risk assessment considers uncertainty in likelihood and impact.","Approval ownership is a governance concern.","Model notation is addressed when specifying and modelling requirements."],"ref":"BABOK Guide v3 §6.3 Assess Risks, printed pp. 120–123; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q647","domains":[5],"level":2,"tag":"","q":"Which are inputs to Assess Risks?","opts":["Business Objectives","Elicitation Results (confirmed)","Influences (internal and external)","Potential Value"],"answer":[0,1,2,3],"why":["Correct: Business Objectives helps identify and discuss potential risks.","Correct: confirmed elicitation results convey stakeholder-perceived risks.","Correct: internal and external influences can affect realization of the future state.","Correct: Potential Value provides a benchmark against which risks can be assessed."],"ref":"BABOK Guide v3 §6.3 Assess Risks, printed pp. 120–123; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-15.html"},{"id":"q648","domains":[5],"level":3,"tag":"","q":"Which stakeholder is described as identifying risks associated with adherence to laws, regulations, or rules?","opts":["Supplier","Project Manager","Tester","Regulator"],"answer":[3],"why":["A Supplier may identify risks associated with using the supplier.","A Project Manager helps assess risk and manages project risk.","A Tester identifies risks from validation or verification perspectives.","Correct: the Regulator identifies risks associated with compliance to laws, regulations, or rules."],"ref":"BABOK Guide v3 §6.3 Assess Risks, printed pp. 120–123; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q649","domains":[5],"level":4,"tag":"","q":"What is a model in Specify and Model Requirements?","opts":["A record of the governance authority for a change","A list of risks and mitigation strategies for the future state","A descriptive and visual way to convey information to an audience to support analysis, communication, and understanding","A repository of approved requirements and designs"],"answer":[2],"why":["Governance authority is defined through governance.","Risks and mitigation strategies are captured in Risk Analysis Results.","Correct: this is the BABOK description of a model.","A repository is a tool for managing business analysis information."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q650","domains":[5],"level":5,"tag":"","q":"Which model formats are explicitly discussed in the elements of Specify and Model Requirements?","opts":["Only prototypes","Matrices","Diagrams","Textual representations"],"answer":[1,2],"why":["Prototypes are a technique, not the only format discussed in the element.","Correct: matrices are described as a model format.","Correct: diagrams are described as a model format.","Text may be used to express requirements, but it is not listed among the model formats in this element."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-15.html"},{"id":"q651","domains":[5],"level":1,"tag":"","q":"Which set includes techniques listed for Specify and Model Requirements?","opts":["Data Modelling, Interface Analysis, Use Cases and Scenarios","Functional Decomposition, Scope Modelling, Workshops","Vendor Assessment, Benchmarking and Market Analysis, Brainstorming","Risk Analysis and Management, Decision Analysis, Root Cause Analysis"],"answer":[0],"why":["Correct: these techniques are listed for §7.1.","These techniques are associated with defining requirements architecture.","These techniques are associated with defining design options.","These techniques are associated with risk and decision analysis tasks."],"ref":"BABOK Guide v3 §7.1 Specify and Model Requirements, printed pp. 136–140; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q652","domains":[5],"level":2,"tag":"","q":"What is a requirements viewpoint?","opts":["A single requirements diagram prepared for one stakeholder","A list of approved design options allocated to solution components","A repository containing all elicitation results","A set of conventions defining how requirements are represented, organized, and related"],"answer":[3],"why":["A view may be a particular representation; the viewpoint sets the conventions.","This describes design options rather than a requirements viewpoint.","A repository is an information management tool.","Correct: a viewpoint defines conventions for representing, organizing, and relating requirements."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–151; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q653","domains":[5],"level":3,"tag":"","q":"Which statements describe the output Requirements Architecture?","opts":["It is the same as a single requirements model","It replaces the need to consider solution scope","It includes requirements and their interrelationships","It may include recorded contextual information"],"answer":[2,3],"why":["An architecture includes the set and relationships, not merely one model.","Solution Scope remains an input and boundary for architecture.","Correct: the architecture includes requirements and their relationships.","Correct: contextual information may also be recorded."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–151; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-15.html"},{"id":"q654","domains":[5],"level":4,"tag":"","q":"Which group is identified as able to assist in defining and confirming the requirements architecture?","opts":["Project Manager, Supplier, Regulator, Customer, End User","Domain Subject Matter Expert, Implementation Subject Matter Expert, Project Manager, Sponsor, Tester","Customer, End User, Regulator, Supplier, Operational Support","Sponsor, Customer, End User, Regulator, Tester"],"answer":[1],"why":["Supplier and customer are not part of the listed five-role group.","Correct: these five roles may assist in defining and confirming the requirements architecture.","These roles may use requirements but are not the listed group for this task.","This group does not match the stakeholder list in §7.4.7."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–151; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q655","domains":[5],"level":5,"tag":"","q":"Which solution approaches are considered when defining design options?","opts":["Create","Purchase","A combination of create and purchase","Approve a single option before analysis"],"answer":[0,1,2],"why":["Correct: creating solution components is an approach.","Correct: purchasing solution components is an approach.","Correct: an option may combine created and purchased components.","Options are defined and assessed before a recommended option is selected."],"ref":"BABOK Guide v3 §7.5 Define Design Options, printed pp. 152–156; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-15.html"},{"id":"q656","domains":[5],"level":1,"tag":"","q":"Which technique is used to identify and analyze existing solutions and market trends?","opts":["Document Analysis","Root Cause Analysis","Item Tracking","Benchmarking and Market Analysis"],"answer":[3],"why":["Document Analysis provides information from existing documents but is not the named technique for market trends.","Root Cause Analysis identifies underlying causes of problems.","Item Tracking manages items such as issues and actions.","Correct: Benchmarking and Market Analysis is used to examine existing solutions and market trends."],"ref":"BABOK Guide v3 §7.5 Define Design Options, printed pp. 152–156; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q657","domains":[5],"level":2,"tag":"","q":"Which output describes various ways to satisfy one or more needs in a context?","opts":["Change Strategy","Requirements Change Assessment","Design Options","Requirements Architecture"],"answer":[2],"why":["Change Strategy describes the approach to transition to a future state.","Requirements Change Assessment analyzes a proposed requirement change.","Correct: Design Options describe ways to satisfy needs in context.","Requirements Architecture organizes requirements and their relationships."],"ref":"BABOK Guide v3 §7.5 Define Design Options, printed pp. 152–156; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q658","domains":[5],"level":3,"tag":"","q":"When may “Do Nothing” be a reasonable recommended action?","opts":["When a requirement has not yet been traced to a design","When the value of a change is low relative to effort, or change risks outweigh staying in the current state","Whenever a solution limitation is identified, regardless of value or risk","Only when all stakeholders approve a replacement solution"],"answer":[1],"why":["Traceability is not the condition described for this recommendation.","Correct: the BABOK gives low relative value or greater change risk as reasons to recommend no action.","A limitation alone does not automatically make change worthwhile.","A replacement solution is not a prerequisite for recommending no action."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q659","domains":[5],"level":4,"tag":"","q":"Which items are guidelines and tools for Recommend Actions to Increase Solution Value?","opts":["Business Objectives","Current State Description","Solution Scope","Requirements Architecture"],"answer":[0,1,2],"why":["Correct: Business Objectives help evaluate solution performance.","Correct: Current State Description provides context for assessing alternatives.","Correct: Solution Scope defines the boundaries for measuring and evaluating the solution.","Requirements Architecture is not listed as a guideline/tool for §8.5."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-15.html"},{"id":"q660","domains":[5],"level":5,"tag":"","q":"Which stakeholder-role pairing is accurate for Recommend Actions to Increase Solution Value?","opts":["Customer: authorizes funding for the recommended actions","End User: ensures adherence to regulations and rules","Regulator: uses the solution as part of the enterprise solution","Sponsor: authorizes and ensures funding for implementation of recommended actions"],"answer":[3],"why":["Funding authorization is attributed to the Sponsor, not Customer.","This describes the role of an End User differently from BABOK.","This describes an End User, not a Regulator.","Correct: the Sponsor authorizes and ensures funding for recommended actions."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–187; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-15.html"},{"id":"q661","domains":[5],"level":1,"tag":"Stakeholder","q":"What is the purpose of Plan Stakeholder Engagement?","opts":["Plan an approach for establishing and maintaining effective working relationships with stakeholders","Plan how business analysis information will be stored and accessed","Plan how elicitation results will be confirmed for accuracy","Plan which requirements and designs will receive formal approval"],"answer":[0],"why":["Correct: §3.2 plans an approach for effective stakeholder working relationships.","This is the purpose of Plan Business Analysis Information Management.","This describes Confirm Elicitation Results.","Approval is addressed by Approve Requirements and governance."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q662","domains":[5],"level":2,"tag":"Stakeholder","q":"Which are inputs to Plan Stakeholder Engagement?","opts":["Business Analysis Approach","Stakeholder Engagement Approach","Elicitation Activity Plan","Needs"],"answer":[0,3],"why":["Correct: the overall approach should be incorporated for consistency.","Stakeholder Engagement Approach is the output of this task, not an input.","Elicitation Activity Plan is an input to Conduct Elicitation.","Correct: Needs helps identify stakeholders and affected parts of the enterprise."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":true,"sourceSet":"ecba-set-16.html"},{"id":"q663","domains":[5],"level":3,"tag":"Stakeholder","q":"Which information is included in the Stakeholder Engagement Approach output?","opts":["Collaboration and communication approaches for the initiative","Approved requirements and designs ready for development","Stakeholder list and analyzed characteristics","Stakeholder roles and responsibilities for the change"],"answer":[0,2,3],"why":["Correct: it identifies collaboration and communication approaches.","Approved requirements and designs are outputs of Approve Requirements.","Correct: the output contains a stakeholder list and analyzed characteristics.","Correct: it records roles and responsibilities for the change."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":true,"sourceSet":"ecba-set-16.html"},{"id":"q664","domains":[5],"level":4,"tag":"Stakeholder","q":"Which activity belongs to Perform Stakeholder Analysis?","opts":["Assess the impact of a proposed change on requirements","Identify stakeholders affected directly or indirectly and analyze their characteristics","Confirm requirements are accurate and consistent with other information","Obtain approval of verified requirements and designs"],"answer":[1],"why":["This is Assess Requirements Changes.","Correct: stakeholder analysis identifies affected stakeholders and analyzes their characteristics.","This is Confirm Elicitation Results.","This is Approve Requirements."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q665","domains":[5],"level":5,"tag":"Stakeholder","q":"Which technique can identify stakeholders who were the source of business rules?","opts":["Business Rules Analysis","Brainstorming","Survey or Questionnaire","Organizational Modelling"],"answer":[0],"why":["Correct: Business Rules Analysis can identify stakeholders who were the source of business rules.","Brainstorming helps produce a stakeholder list and identify roles and responsibilities.","Surveys identify shared characteristics of stakeholder groups.","Organizational Modelling helps identify affected units and people and their needs."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q666","domains":[5],"level":1,"tag":"Stakeholder","q":"Which option accurately identifies stakeholder sources described in Plan Stakeholder Engagement?","opts":["Customer—internal; End User—external; Supplier—external","Customer—external; End User—external; Supplier—internal","Customer—internal; End User—internal; Supplier—external","Customer—external; End User—internal; Supplier—external"],"answer":[3],"why":["Customer and End User are reversed.","End User and Supplier are reversed.","Customer is not identified as an internal source in this guidance.","Correct: BABOK identifies Customers and Suppliers as sources of external stakeholders, and End Users as a source of internal stakeholders."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q667","domains":[5],"level":2,"tag":"Stakeholder","q":"What is the purpose of Conduct Elicitation?","opts":["Ensure stakeholders have a shared understanding of business analysis information","Encourage stakeholders to work towards a common goal","Draw out, explore, and identify information relevant to the change","Check elicitation information for accuracy and consistency with other information"],"answer":[2],"why":["This is Communicate Business Analysis Information.","This is Manage Stakeholder Collaboration.","Correct: this is the purpose of Conduct Elicitation.","This is Confirm Elicitation Results."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q668","domains":[5],"level":3,"tag":"Stakeholder","q":"Which input is listed for Conduct Elicitation?","opts":["Requirements (verified)","Elicitation Activity Plan","Elicitation Results (unconfirmed)","Stakeholder Engagement"],"answer":[1],"why":["Requirements (verified) is an input to Approve Requirements.","Correct: the Elicitation Activity Plan provides planned activities, techniques, logistics, scope, and background sources.","Elicitation Results (unconfirmed) is an output of Conduct Elicitation.","Stakeholder Engagement is an output of Manage Stakeholder Collaboration."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q669","domains":[5],"level":4,"tag":"Stakeholder","q":"When guiding an elicitation activity, which considerations help keep it focused on the intended outcomes?","opts":["Activity goals and agenda","Scope of the change","Proposed representation and desired level of detail","Final approval authority for requirements"],"answer":[0,1,2],"why":["Correct: activity goals and agenda help guide the work.","Correct: scope helps keep elicitation focused.","Correct: planned representations and appropriate detail support intended outcomes.","Approval authority is defined through governance, not as an elicitation-guidance consideration."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":true,"sourceSet":"ecba-set-16.html"},{"id":"q670","domains":[5],"level":5,"tag":"Stakeholder","q":"Which three stakeholder roles are specifically included in Conduct Elicitation?","opts":["Customer, Project Manager, Regulator","Domain Subject Matter Expert, Project Manager, Sponsor","End User, Supplier, Regulator","Customer, Domain Subject Matter Expert, End User"],"answer":[3],"why":["Project Manager and Regulator are not among the specific roles listed for this task.","Project Manager is not listed as one of these Conduct Elicitation roles.","Supplier and Regulator are not among the listed roles in §4.2.7.","Correct: Customer, Domain Subject Matter Expert, and End User are named roles; Implementation Subject Matter Expert, Sponsor, and any other relevant stakeholders are also addressed."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q671","domains":[5],"level":1,"tag":"Stakeholder","q":"What is the output of Conduct Elicitation?","opts":["Business Analysis Information (communicated)","Stakeholder Engagement Approach","Elicitation Results (unconfirmed)","Elicitation Results (confirmed)"],"answer":[2],"why":["Communicated information is produced by Communicate Business Analysis Information.","This is the output of Plan Stakeholder Engagement.","Correct: Conduct Elicitation produces captured results in a format specific to the elicitation activity; they are unconfirmed.","Confirmed results are produced by Confirm Elicitation Results."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q672","domains":[5],"level":2,"tag":"Stakeholder","q":"Which are the common types of elicitation described in BABOK?","opts":["Approval","Collaborative","Research","Experiments"],"answer":[1,2,3],"why":["Approval is not one of the three common elicitation types.","Correct: Collaborative is a common type.","Correct: Research is a common type.","Correct: Experiments are a common type."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":true,"sourceSet":"ecba-set-16.html"},{"id":"q673","domains":[5],"level":3,"tag":"Stakeholder","q":"What is the purpose of Communicate Business Analysis Information?","opts":["Ensure stakeholders have a shared understanding of business analysis information","Capture information relevant to the change through elicitation","Encourage stakeholders to work towards a common goal","Obtain agreement on and approval of requirements and designs"],"answer":[0],"why":["Correct: this is the purpose of Communicate Business Analysis Information.","This is Conduct Elicitation.","This is Manage Stakeholder Collaboration.","This is Approve Requirements."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q674","domains":[5],"level":5,"tag":"Stakeholder","q":"Which factors are considered when determining communication objectives and format?","opts":["Contractual or regulatory constraints","Only the level of detail in the requirement, regardless of the audience","Audience and what each stakeholder needs from the communication","Stakeholders’ preferred communication or learning style"],"answer":[0,2,3],"why":["Correct: contractual and regulatory constraints can affect the package.","The BABOK calls for audience-appropriate communication, not a single detail level regardless of audience.","Correct: the audience and its needs inform the package.","Correct: communication preferences and learning styles are considered."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71","multi":true,"sourceSet":"ecba-set-16.html"},{"id":"q675","domains":[5],"level":1,"tag":"Stakeholder","q":"Which guideline/tool describes how information will be disseminated, including detail, formality, and frequency?","opts":["Stakeholder Engagement output","Business Analysis Approach","Information Management Approach","Governance Approach"],"answer":[1],"why":["Stakeholder Engagement output records willingness to participate, not communication dissemination rules.","Correct: the Business Analysis Approach describes how information will be disseminated and the expected detail, formality, and frequency.","The Information Management Approach helps determine how information is packaged and communicated.","Governance Approach identifies decision and approval responsibilities."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q676","domains":[5],"level":2,"tag":"Stakeholder","q":"Which technique is matched correctly to communicating business analysis information?","opts":["Interviews—individually communicate information to stakeholders","Reviews—used only for individual communication and never approvals","Workshops—used only to send formal documentation without feedback","Interviews—used primarily to establish stakeholder approval authority"],"answer":[0],"why":["Correct: Interviews can communicate information to stakeholders individually.","Reviews may be group or individual and can support feedback and approvals.","Workshops allow feedback, adjustments, consensus, and approvals.","Approval authority is identified through the Governance Approach."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q677","domains":[5],"level":3,"tag":"Stakeholder","q":"When is business analysis information considered communicated?","opts":["When the business analyst distributes a document to the stakeholder list","When a stakeholder confirms receipt, even without understanding","When the information is formally approved","When target stakeholders understand its content and implications"],"answer":[3],"why":["Distribution alone does not establish shared understanding.","Receipt alone does not establish understanding.","Approval may follow communication but is not the definition of communicated information.","Correct: communication is achieved when target stakeholders understand content and implications."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q678","domains":[5],"level":4,"tag":"Stakeholder","q":"What is the purpose of Manage Stakeholder Collaboration?","opts":["Communicate information so stakeholders understand its content","Obtain approval of requirements and designs","Encourage stakeholders to work towards a common goal","Plan an approach for establishing working relationships"],"answer":[2],"why":["This is Communicate Business Analysis Information.","This is Approve Requirements.","Correct: this is the purpose of Manage Stakeholder Collaboration.","This is Plan Stakeholder Engagement."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–74","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q679","domains":[5],"level":5,"tag":"Stakeholder","q":"Which are inputs to Manage Stakeholder Collaboration?","opts":["Business Analysis Information (communicated)","Stakeholder Engagement Approach","Business Analysis Performance Assessment","Stakeholder Engagement"],"answer":[1,2],"why":["Communicated information is not a listed input to this task.","Correct: this approach describes expected stakeholder engagement and how stakeholders may need to be managed.","Correct: the assessment informs the effectiveness of BA tasks, including stakeholder engagement.","Stakeholder Engagement is the output of this task."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–74","multi":true,"sourceSet":"ecba-set-16.html"},{"id":"q680","domains":[5],"level":1,"tag":"Stakeholder","q":"Which practices are elements of Manage Stakeholder Collaboration?","opts":["Gain agreement on commitments","Monitor stakeholder engagement","Support collaboration and a free flow of information and ideas","Approve requirements on behalf of stakeholders"],"answer":[0,1,2],"why":["Correct: agreeing commitments is an element.","Correct: monitoring participation, attitudes, results, and commitments is an element.","Correct: collaboration supports free-flowing information and shared effort.","The business analyst facilitates approval; stakeholders with authority approve requirements."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–74","multi":true,"sourceSet":"ecba-set-16.html"},{"id":"q681","domains":[5],"level":2,"tag":"Stakeholder","q":"Which technique is used to stimulate teamwork by immersing participants in a safe and fun situation?","opts":["Lessons Learned","Risk Analysis and Management","Stakeholder List, Map, or Personas","Collaborative Games"],"answer":[3],"why":["Lessons Learned help understand satisfaction and improve working relationships.","Risk Analysis and Management addresses risks to stakeholder involvement and engagement.","Stakeholder List, Map, or Personas helps identify participants and relationships.","Correct: Collaborative Games stimulate teamwork and collaboration in a safe, engaging situation."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–74","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q682","domains":[5],"level":3,"tag":"Stakeholder","q":"Who may be involved in collaboration during a change, according to the stakeholder guidance?","opts":["Only the customer and end user","Only stakeholders with approval authority","All stakeholders","Only the project manager and sponsor"],"answer":[2],"why":["This excludes many stakeholder groups.","Collaboration is broader than formal approval authority.","Correct: all types of stakeholders may be involved in collaboration during change.","This excludes stakeholders who may contribute relevant knowledge or work."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–74","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q683","domains":[5],"level":4,"tag":"Stakeholder","q":"What does the Stakeholder Engagement output represent?","opts":["A summary of elicitation information awaiting confirmation","Stakeholders’ willingness to engage in business analysis activities and interact with the business analyst when needed","The list of stakeholders, analyzed characteristics, roles, and communication approach","A formal record that requirements have been approved"],"answer":[1],"why":["This describes Elicitation Results (unconfirmed).","Correct: Stakeholder Engagement is the willingness of stakeholders to participate and interact when necessary.","This describes the Stakeholder Engagement Approach output of Plan Stakeholder Engagement.","This describes approved requirements or designs."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–74","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q684","domains":[5],"level":5,"tag":"Stakeholder","q":"What is the purpose of Approve Requirements?","opts":["Obtain agreement on and approval of requirements and designs so business analysis work or solution construction can proceed","Confirm elicitation information is accurate and consistent","Determine the relationships among requirements and designs","Assess the impact and urgency of a proposed requirements change"],"answer":[0],"why":["Correct: this is the purpose of Approve Requirements.","This is Confirm Elicitation Results.","This is Trace Requirements.","This is Assess Requirements Changes."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q685","domains":[5],"level":1,"tag":"Stakeholder","q":"Which are inputs to Approve Requirements?","opts":["Designs","Requirements (specified and modelled) only","Elicitation Results (unconfirmed)","Requirements (verified)"],"answer":[0,3],"why":["Correct: designs ready for further specification and development are an input.","The task specifically lists verified requirements, not only specified and modelled requirements.","Unconfirmed elicitation results are not ready for approval.","Correct: verified requirements are an input."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98","multi":true,"sourceSet":"ecba-set-16.html"},{"id":"q686","domains":[5],"level":2,"tag":"Stakeholder","q":"In Understand Stakeholder Roles, what must the business analyst establish for the approval process?","opts":["That every stakeholder has equal authority to approve","That approval authority can be assumed from job title alone","Who holds decision-making responsibility and authority for sign-off","Which stakeholders may need to be consulted or informed"],"answer":[2,3],"why":["The BABOK notes that only some stakeholders have approval authority.","Roles and authority are defined through the governance process, not assumed.","Correct: the BA needs to understand decision responsibility and sign-off authority.","Correct: influential stakeholders may need consultation or information."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98","multi":true,"sourceSet":"ecba-set-16.html"}]);